try:
    # Generated by the release workflow; may be absent in a dev checkout.
    from _version import __version__
except ImportError:
    __version__ = "0.0.0-dev"

from packaging import version
import requests


class VersionChecker:
    REPO = "Loukious/StreamlabsTikTokStreamKeyGenerator"

    @classmethod
    def check_update(cls):
        """Return update info dict if a newer release exists, else None.

        Raises on network/API errors so callers can distinguish
        "no update available" from "update check failed".
        """
        response = requests.get(
            f"https://api.github.com/repos/{cls.REPO}/releases/latest",
            timeout=10
        )
        response.raise_for_status()
        release = response.json()
        latest = release["tag_name"].lstrip('v')

        try:
            has_update = version.parse(latest) > version.parse(__version__)
        except version.InvalidVersion:
            # Local dev version ("x.y.z-dev") can't be compared reliably.
            has_update = False

        if has_update:
            return {
                "current": __version__,
                "latest": latest,
                "url": release["html_url"],
                "notes": release.get("body", "")
            }
        return None